TLM.f("Tempora/Quad2-0",{"officium":"Dominica II in Quadragesima","rule":["no Gloria","Credo","Prefatio=Quad","Suffragium=Sanctorum;Vivis;;"],"sections":{"Introitus":[{"k":"ref","la":"Ps 24:6; 24:3; 24:22"},{"k":"text","la":"Reminíscere miseratiónum tuarum, Dómine, et misericórdiæ tuæ, quæ a sǽculo sunt: ne umquam dominéntur nobis inimíci nostri: líbera nos, Deus Israël, ex ómnibus angústiis nostris."},{"k":"ref","la":"Ps 24:1-2"},{"k":"text","la":"Ad te, Dómine, levávi ánimam meam: Deus meus, in te confído, non erubéscam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Reminíscere miseratiónum tuarum, Dómine, et misericórdiæ tuæ, quæ a sǽculo sunt: ne umquam dominéntur nobis inimíci nostri: líbera nos, Deus Israël, ex ómnibus angústiis nostris."}],"Oratio":[{"k":"text","la":"Deus, qui cónspicis omni nos virtúte destítui: intérius exteriúsque custódi; ut ab ómnibus adversitátibus muniámur in córpore, et a pravis cogitatiónibus mundémur in mente."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Thessalonicénses"},{"k":"ref","la":"1 Thess 4:1-7"},{"k":"text","la":"Fratres: Rogámus vos et obsecrámus in Dómino Jesu: ut, quemádmodum accepístis a nobis, quómodo opórteat vos ambuláre et placére Deo, sic et ambulétis, ut abundétis magis. Scitis enim, quæ præcépta déderim vobis Per Dominum Jesum. Hæc est enim volúntas Dei, sanctificátio vestra: ut abstineátis vos a fornicatióne, ut sciat unusquísque vestrum vas suum possidére in sanctificatióne et honóre; non in passióne desidérii, sicut et gentes, quæ ignórant Deum: et ne quis supergrediátur neque circumvéniat in negótio fratrem suum: quóniam vindex est Dóminus de his ómnibus, sicut prædíximus vobis et testificáti sumus. Non enim vocávit nos Deus in immundítiam, sed in sanctificatiónem: in Christo Jesu, Dómino nostro."}],"Graduale":[{"k":"ref","la":"Ps 24:17-18"},{"k":"text","la":"Tribulatiónes cordis mei dilatátæ sunt: de necessitátibus meis éripe me, Dómine,"},{"k":"text","la":"Vide humilitátem meam et labórem meum: et dimítte ómnia peccáta mea.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 105:1-4"},{"k":"text","la":"Confitémini Dómino, quóniam bonus: quóniam in sǽculum misericórdia ejus."},{"k":"text","la":"Quis loquétur poténtias Dómini: audítas fáciet omnes laudes ejus?","mark":"V"},{"k":"text","la":"Beáti, qui custódiunt judícium et fáciunt justítiam in omni témpore.","mark":"V"},{"k":"text","la":"Meménto nostri, Dómine, in beneplácito pópuli tui: vísita nos in salutári tuo.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 17:1-9"},{"k":"text","la":"In illo témpore: Assúmpsit Jesus Petrum, et Jacóbum, et Joánnem fratrem eius, et duxit illos in montem excélsum seórsum: et transfigurátus est ante eos. Et resplénduit fácies ejus sicut sol: vestiménta autem ejus facta sunt alba sicut nix. Et ecce, apparuérunt illis Móyses et Elías cum eo loquéntes. Respóndens autem Petrus, dixit ad Jesum: Dómine, bonum est nos hic esse: si vis, faciámus hic tria tabernácula, tibi unum, Móysi unum et Elíæ unum. Adhuc eo loquénte, ecce, nubes lúcida obumbrávit eos. Et ecce vox de nube, dicens: Hic est Fílius meus diléctus, in quo mihi bene complácui: ipsum audíte. Et audiéntes discípuli, cecidérunt in fáciem suam, et timuérunt valde. Et accéssit Jesus, et tétigit eos, dixítque eis: Súrgite, et nolíte timére. Levántes autem óculos suos, néminem vidérunt nisi solum Jesum. Et descendéntibus illis de monte, præcépit eis Jesus, dicens: Némini dixéritis visiónem, donec Fílius hóminis a mórtuis resúrgat."}],"Offertorium":[{"k":"ref","la":"Ps 118:47; 118:48"},{"k":"text","la":"Meditábor in mandátis tuis, quæ diléxi valde: et levábo manus meas ad mandáta tua, quæ diléxi."}],"Secreta":[{"k":"text","la":"Sacrifíciis præséntibus, Dómine, quǽsumus, inténde placátus: ut et devotióni nostræ profíciant et salúti."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 5:2-4"},{"k":"text","la":"Intéllege clamórem meum: inténde voci oratiónis meæ, Rex meus et Deus meus: quóniam ad te orábo, Dómine."}],"Postcommunio":[{"k":"text","la":"Súpplices te rogámus, omnípotens Deus: ut quos tuis réficis sacraméntis, tibi étiam plácitis móribus dignánter deservíre concédas."},{"k":"macro","name":"Per Dominum"}]},"hr":{"5c4eeb26ffbfd3f2":{"t":"Ps 24, 6, 3 i 22, Ps 24, 1-2\n(Ps 24, 6, 3 i 22) Spomeni se, Gospodine, svojih smilovanja i svoga milosrđa koje je odvijeka, da nikad ne zavladaju nad nama naši neprijatelji. Bože Izraelov, izbavi svoj narod od svih njegovih nevolja. (Ps 24, 1-2) K tebi, Gospodine, uzdižem svoju dušu, u tebe se uzdam. Ne daj da se postidim.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 24, 6, 3 i 22) Spomeni se, Gospodine, svojih smilovanja i svoga milosrđa koje je odvijeka, da nikad ne zavladaju nad nama naši neprijatelji. Bože Izraelov, izbavi svoj narod od svih njegovih nevolja.","kn":"(Ps. 24, 6, 3, 22). Opomeni se samilosti svoje. Gospodine, i milosrđa svoga, što je od vijeka, da nikad ne zavladaju nad nama neprijatelji naši; izbavi nas. Bože, iz svih tjeskoba naših! (Ps. 24, 1, 2). K Tebi, Gospodine, dižem dušu svoju. Bože moj. u Te se ufam, ne daj, da se zastddim! Slava Ocu . . . Opomeni se . . .","knRef":"Kniewald 1942, str. 128–129 (snimka 65) (OCR)"},"ffa4d22f33d657ce":{"t":"<i>Pomolimo se</i>.\nBože, koji vidiš da nas izdaju sve sile, štiti nas iznutra i izvana, da se očuvamo od svake tjelesne nezgode i od zlih misli očistimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji vidiš, da smo bez svake snage, čuvaj nas izvana i iznutra, te nas obrani od svih tjelesnih suprotivština i očisti nam duše od svih zlih misli, po G. n.","knRef":"Kniewald 1942, str. 130–131 (snimka 66) (OCR)"},"3644b33335c86ae5":{"t":"1 Sol 4, 1-7\nČitanje Poslanice bl. Pavla apostola Solunjanima. Braćo: Molimo vas i zaklinjemo u Gospodinu Isusu, da živite kao što ste naučili od nas kako treba živjeti i ugađati Bogu, da biste bolje napredovali. Vi dobro znate koje sam vam zapovijedi dao u Gospodinu Isusu. – Božja je volja vaše posvećenje: naime, da se čuvate nečistoće, da se svatko od vas zna služiti svojim tijelom u svetosti i časti, a ne da se prepušta pužudama kao što čine pogani koji ne poznaju Boga. Da nitko u tome ne vrijeđa i ne vara svojega brata, jer je osvetnik za sve ovo Gospodin, kao što smo vam već naglasili i posvjedočili. Bog nas nije pozvao na nečistoću, nego na svetost u našem Gospodinu Isusu Kristu.","kn":"Čitanje poslanice bi. Pavla apostola Solunjanlma (I, 4, 1-7). Braćo! Molimo vas i opominjemo u Gospodinu Isusu, da živite tako, kao što ste naučili od nas, kako vam treba živjeti i ugađati Bogu, da više napredujete. Jer znate, kakve sam vam dao zaipovijedi u Gospođinu Isusu. Božja volja je vaša svetost: da se čuvate bludnosti, da svaki od vas zna svoje tijelo držati u svetosti i časti, ne u strasti požude kao neznabošci, koji ne poznaju Boga. A neka nitko ne zaskoči i ne prevari svoga brata, jer je Gospodin osvetnik za sve ovo, kako vam i prije rekosmo i zasvijedočismo. Jer nas Bog nije pozvao na nečistoću, nego na svetost u Isusu Kristu, Gospodinu našemu.","knRef":"Kniewald 1942, str. 130–131 (snimka 66) (OCR)"},"475a9e8fcab7844c":{"t":"Ps 24, 17-18\nUmnožile su se nevolje mog srca. Iz mojih me tjeskoba izbavi, Gospodine. Pogledaj moju bijedu i moju muku i oprosti sve moje prestupke.\n\nPs 105, 1-4\nHvalite Gospodina jer je dobar, jer je vječno milosrđe njegovo. Tko može iskazati moć Gospodnju, razglasiti svu hvalu njegovu? Blago onima koji žive pravo, koji u svako vrijeme čine što je pravedno. Sjeti se nas, Gospodine, u blagostanju naroda tvojega, pohodi nas spasenjem svojim.","kn":"(Ps. 24, 17, 18). Umnožile su se nevolje srca mojega, iz tjeskoba mojih izbavi me, Gospodine! Vidi poniženje moje i muku moju i oprosti mi sve grijehe moje.\n\n(Ps. 105, 1_4). Slavite Gospodina, jer je dobar, jer je dovijeka milosrđe njegovo! Tko će pripovijedati moćna djela Gospo'dnja', tko će :^evati njegovu slavu? Blaženi oni, koji su ispravni i čine pravdu u svako doba. Sjeti nas se. Gospodine, u brizi svojoj za narod svoj, i posjeti nas spasenjem svojim!","knRef":"Kniewald 1942, str. 130–131 (snimka 66) (OCR)"},"47598764b5506c06":{"t":"Mt 17, 1-9\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: uze Isus sa sobom Petra, Jakova i njegova brata Ivana, i povede ih nasamo na visoku goru te se preobrazi pred njima. Njegovo lice zasja kao sunce, a haljine mu pobijeliše kao snijeg. I gle, ukažu im se Mojsije i Ilija razgovarajući s njim. Tada Petar reče Isusu: Gospodine, dobro nam je ovdje. Ako hoćeš, ovdje ćemo podići tri sjenice: jednu tebi, jednu Mojsiju, jednu Iliji. Dok je on još govorio, prekrije ih svijetao oblak. I gle, iz oblaka se čuo glas: Ovo je moj ljubljeni Sin koji mi je po volji, njega slušajte! – Kad su to učenici čuli, padnu ničice silno prestrašeni. Isus im pristupi, dotače ih se i reče: Ustanite i ne bojte se! Oni podignu oči i ne vidješe nikoga, osim Isusa. I dok su silazili s gore, Isus im naloži: Ne govorite nikome o viđenju, dok Sin Čovječji ne uskrsne od mrtvih.","v":"et → ∅","kn":"t Slijedi sveto evanđelje po Mateju (17, 1-9). U ono vrijeme uze Isus Petra i Jakova i njegova brata Ivana, i povede ih nasamo, na visoku goru, i preobrazi se pred njima. I lice mu zasja kao sunce, a Ponedjeljak iz.i U. nedjelje u korizmi njegove haljine postadoše bijele kao snijeg. I ukazaše im se Mojsije i Ilija govoreći s njim. Tada Petar reče: Gospodine, dobro nam je biti ovdje. Ako hoćeš, načinit ćemo tri sjenice: jednu tebi, jednu Mojsiju d jednu Iliji. Dok je on još govorio, zasjeni ih uto sjajan oblak. I glas s neba progovori: Ovo je moj ljubljeni Sin, koji mi je omilio: njega slušajte! Kad su to čuli njegovi učenici, padoše ničice i . silno se prepadoše. I pristupi im Isus, dotače ih se i reče im: Ustanite i ne bojte se! .A kad su podigli svoje oči, nijesu nikoga, vidjeli nego samo Isusa. I dok su silazili s gore, Isus im zabrani: Nikomu ne govorite o viđenju, dok Sin čovječji ne uskrsne od mrtvih.","knRef":"Kniewald 1942, str. 130–131 (snimka 66) (OCR)"},"2ec64dc83a890437":{"t":"Ps 118, 47-48\nRazmišljat ću o tvojim zapovijedima koje veoma ljubim. I svoje ću ruke uzdići k tvojim zapovijedima koje volim.","kn":"(Ps. 118, 47, 48). Razmišljam^ o zapovijedima Tvojim, koje veoma ljubim i uzdižem ruke svoje k zapovijedima Tvojim, koje ljubim.","knRef":"Kniewald 1942, str. 350–351 (snimka 176) (OCR)"},"90a1614471aa68a1":{"t":"Umilostivljen pogledaj, molimo, Gospodine, na ove žrtve, da koriste i našoj pobožnosti i spasenju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pogledaj, Gospodine, molimo Te, milostivo na ove žrtve i podaj, da koriste i našoj pobožnosti i spasenju, po G. n.","knRef":"Kniewald 1942, str. 130–131 (snimka 66) (OCR)"},"8e0447f4695d07e4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti tjelesnim postom suzbijaš opačine, uzdižeš dušu, daješ krepost i nagrade po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo 1 spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože. koji tjelesnim postom obuzdavaš opačine, duh dižeš, daješ krepost i nagrade,' po Kristu, Gospodinu našemu; po kojem veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti, Nebesa Te 1 nebeske Red i čin sv. mise moći i blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se s njima smiju sjediniti i naši glasovi, koji govore u smjernom ispovijedanju:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"b74f00823a6760a8":{"t":"Ps 5, 2-4\nČuj moj vapaj, pripazi na glas moje molitve, Kralju moj i Bože moj, jer se tebi molim, Gospodine.","kn":"(Ps. 5, 2-4). Razumij vapaj moj, pazi na glas molitve moje. Kralju moj i Bože moj, jer se Tebi molim.","knRef":"Kniewald 1942, str. 130–131 (snimka 66) (OCR)"},"46abd48177cf9e44":{"t":"<i>Pomolimo se</i>.\nPonizno te molimo, svemogući Bože, udijeli da ti služe i ugode dostojnijim vladanjem oni koje krijepiš svojim otajstvima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Ponizno Te molimo, svemogući Bože, podaj, da Ti ugodnim vladanjem dostojno služe u životu, koje krijepiš svojim svetotajstvima, po G. n. I. K.","knRef":"Kniewald 1942, str. 98–99 (snimka 50) (OCR)"}}});
